-- fase87a_jce_colegios_2026_respaldo_y_carga.sql · Análisis Electoral (esquema public)
-- Idempotente. NO modifica jce_recinto ni jce_colegio: solo respalda y carga una tabla de trabajo.
--
-- Fuente: archivos de la JCE recibidos el 6 oct 2026 (electoral/jce-2026-09/):
--   04/05  Colegios creados y distribuidos 2024-2028, corte 30 sep 2026: 1,218 colegios, 140 municipios
--   08     Colegios creados por municipio, corte 23 sep 2026: 1,157 colegios con electores (163,249) y año de creación
--   06/07  Colegios preliminares 2026: 382 (subconjunto de 08), 4,509 electores
--   03     Totales JCE al 30 sep 2026: 4,568 recintos, 18,545 colegios
-- Cuadre entre archivos: los 1,218 del 30 sep contienen los 1,157 del 23 sep; los 61 restantes (propuesta 10)
-- no tienen electores todavía. En 20 colegios el recinto del 23 sep difiere del 30 sep (se guarda el anterior).
--
-- Paso 1. Respaldo con fecha de las tablas actuales (solo si no existe ya).
create table if not exists public.jce_recinto_bak_20261007 as select * from public.jce_recinto;
create table if not exists public.jce_colegio_bak_20261007 as select * from public.jce_colegio;

-- Paso 2. Tabla de trabajo con lo que dice la JCE.
drop table if exists public.jce_colegios_nuevos_2026;
create table public.jce_colegios_nuevos_2026 (
  id_municipio      smallint not null,   -- código JCE del municipio (columna «Serie» del reporte 04)
  municipio_jce     text not null,
  codigo_recinto    text not null,       -- 5 dígitos, dentro del municipio
  recinto           text not null,
  direccion         text,
  sector            text,
  codigo_colegio    text not null,       -- 4 dígitos, dentro del municipio
  electores         integer,             -- del reporte 08 (corte 23 sep); null en los 61 de la propuesta 10
  anio_creacion     integer,             -- 2024, 2025 o 2026; null en los 61
  preliminar        boolean,             -- true = «ColegioPreliminar» (382)
  codigo_recinto_23sep text,             -- solo cuando el recinto del 23 sep era otro (20 casos)
  -- columnas de cruce, las llena el paso 3
  id_recinto_actual integer,
  id_colegio_actual integer,
  situacion         text,
  primary key (id_municipio, codigo_colegio)
);

-- Paso 3. Cruce contra lo que hay hoy. El recinto se identifica por (municipio, código de recinto) a través
-- de los colegios existentes, porque jce_recinto no guarda el municipio directamente.
update public.jce_colegios_nuevos_2026 n
   set id_colegio_actual = c.id_colegio, id_recinto_actual = c.id_recinto
  from public.jce_colegio c
 where c.id_municipio = n.id_municipio and c.codigo_colegio = n.codigo_colegio;
update public.jce_colegios_nuevos_2026 n
   set id_recinto_actual = x.id_recinto
  from (select distinct c.id_municipio, r.codigo_recinto, c.id_recinto
          from public.jce_colegio c join public.jce_recinto r on r.id = c.id_recinto) x
 where n.id_recinto_actual is null and x.id_municipio = n.id_municipio and x.codigo_recinto = n.codigo_recinto;
update public.jce_colegios_nuevos_2026 n
   set situacion = case
     when id_colegio_actual is not null and exists (select 1 from public.jce_colegio c join public.jce_recinto r on r.id = c.id_recinto
                                                     where c.id_colegio = n.id_colegio_actual and r.codigo_recinto = n.codigo_recinto) then 'ya existe'
     when id_colegio_actual is not null then 'existe en otro recinto'
     when id_recinto_actual is not null then 'falta colegio (recinto existe)'
     else 'falta colegio y recinto' end;

-- Comprobación (sin sesión). Esperado: total = 1218, con_electores = 1157, preliminares = 382, respaldo_colegios = cantidad actual de jce_colegio.
select count(*) as total, count(electores) as con_electores, count(*) filter (where preliminar) as preliminares,
       count(distinct id_municipio) as municipios, sum(electores) as electores,
       (select count(*) from public.jce_colegio_bak_20261007) as respaldo_colegios,
       (select count(*) from public.jce_recinto_bak_20261007) as respaldo_recintos
  from public.jce_colegios_nuevos_2026;
